try {
  const rawInput = $input.first()?.json || {};
  const workflow = rawInput.workflow || {};
  const execution = rawInput.execution || {};
  const errorObj = execution.error || rawInput.error || {};

  const workflowName = workflow.name || rawInput.workflow_name || 'Unknown Workflow';
  const workflowId = workflow.id || rawInput.workflow_id || 'N/A';
  const executionId = execution.id || rawInput.execution_id || ('err_' + Date.now());
  const lastNode = execution.lastNodeExecuted || rawInput.last_node || 'Unknown Node';
  const errorMessage = errorObj.message || errorObj.description || rawInput.error_message || 'Workflow execution failure';
  const errorStack = errorObj.stack || '';

  // Determine Transient vs Manual Review
  let remediationStrategy = 'MANUAL_REVIEW_REQUIRED';
  let isTransient = false;

  if (errorMessage.includes('ECONNREFUSED') || errorMessage.includes('ETIMEDOUT') || errorMessage.includes('socket hang up')) {
    remediationStrategy = 'RETRY_TRANSIENT_NETWORK';
    isTransient = true;
  } else if (errorMessage.includes('429') || errorMessage.includes('rate limit') || errorMessage.includes('Too Many Requests')) {
    remediationStrategy = 'RATE_LIMIT_BACKOFF';
    isTransient = true;
  } else if (errorMessage.includes('JWT') || errorMessage.includes('401') || errorMessage.includes('Unauthorized')) {
    remediationStrategy = 'REFRESH_AUTH_TOKEN';
  }

  const validationErrors = [errorMessage];
  const isManualReview = !isTransient;
  const status = isManualReview ? 'NEEDS_MANUAL_REVIEW' : 'FAILED';

  return {
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    last_node: lastNode,
    status: status,
    error_message: errorMessage,
    remediation_strategy: remediationStrategy,
    is_transient: isTransient,
    is_manual_review: isManualReview,
    validation_errors: validationErrors,
    timestamp: new Date().toISOString(),
    raw_payload: rawInput,
    payload: {
      workflow: workflow,
      execution_id: executionId,
      last_node: lastNode,
      error: errorMessage,
      validation_errors: validationErrors,
      raw_input_snapshot: rawInput,
      stack_snippet: errorStack ? errorStack.split('\n').slice(0, 5).join('\n') : null
    }
  };
} catch (catchErr) {
  return {
    workflow_name: 'OpenBalancerGlobalErrorHandler_Fallback',
    workflow_id: 'fallback',
    execution_id: 'err_fallback_' + Date.now(),
    last_node: 'Parse Error Diagnostics',
    status: 'NEEDS_MANUAL_REVIEW',
    error_message: String(catchErr.message || catchErr),
    remediation_strategy: 'FALLBACK_CATCH',
    is_transient: false,
    is_manual_review: true,
    validation_errors: [String(catchErr.message || catchErr)],
    timestamp: new Date().toISOString(),
    raw_payload: { fallback_raw: $input.first()?.json || {} },
    payload: { fallback_error: String(catchErr) }
  };
}
